'use strict';

var escape = require('../helpers/escape');

function _render(context, options) {

	var $ = context.jQuery,
		PubSub = context.PubSub;

	var name = options.name ? options.name : 'send',
		attrib = escape.htmlAttributeEscape(JSON.stringify(options), { singleQuotes: true });

	//HTML
	var $html = $(
		'<hr>' +
		'<div class="form-group">' +
			'<button type="button" name="' + name + '" class="btn btn-block btn-success f3-send" data-options=\'' + attrib + '\'>' +
				options.text +
			'</button>' +
		'</div>'
	);

	//Bind
	$html.find('button').on('click', function (e) {

		//Prevent submit
		e.preventDefault();

		var $this = $(this),
			$tree = $this.parents('.f3-branch').parent(),
			valid = true;

		//trigger validation for all visible branches
		$.each($tree.children('.f3-branch:visible'), function () {

			var validator = $(this).validate(context.settings.validate);
			valid = valid && validator.form();

		});

		if (valid) {
			//Publish the event
			PubSub.publish('f3.send', {
				'trigger': this,
				'event': 'success'
			});
		}

	});

	return $html;

}

function _read() {

	return null;

}

module.exports = {
	render: _render,
	read: _read,
	name: 'send'
};
